import { test, expect } from '@playwright/test';

test.describe('File Upload - Upload Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should successfully upload a small text file and display confirmation', async ({ page }) => {
    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and select a small text file using getByLabel
    const fileSelect = page.getByLabel(/select file/i);
    await fileSelect.click();

    // Locate and click the submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for the upload confirmation page to load
    await page.waitForURL('**/upload-confirmation');

    // Verify the page title contains 'File Uploaded!'
    const pageTitle = page.getByRole('heading', { name: /file uploaded/i });
    await expect(pageTitle).toBeVisible();

    // Verify the uploaded file's name is displayed
    const uploadedFiles = page.getByRole('region', { name: /uploaded files/i });
    await expect(uploadedFiles).toBeVisible();
    const fileName = page.getByText(/sample.txt/i);
    await expect(fileName).toBeVisible();

    // Verify the confirmation message is visible
    const confirmationMessage = page.getByText(/file uploaded successfully/i);
    await expect(confirmationMessage).toBeVisible();
  });

  test('should handle empty file selection and display error message', async ({ page }) => {
    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and click the submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for the error page to load
    await page.waitForURL('**/upload-error');

    // Verify the error message is displayed
    const errorMessage = page.getByText(/no file selected/i);
    await expect(errorMessage).toBeVisible();

    // Verify the file input is still visible
    await expect(fileInput).toBeVisible();

    // Verify the file input is still enabled
    await expect(fileInput).toBeEnabled();
  });
});
